print('Layers:')
for layer in doc.layers:
    print(f'  {layer.dxf.name}')
print()
print('=== Entities on key layers ===')
for layer in ['A-PARAPET', 'A-SCREEN', 'A-OPENING', 'A-ROOF', 'M-EQUIP', 'M-CURB', 'M-SCREEN']:
