    if entities:
        print(f'\n--- Layer: {layer} ({len(entities)} entities) ---')
        for e in entities[:20]:
            if e.dxftype() == 'LWPOLYLINE':
                pts = [(float(v[0]), float(v[1])) for v in e.vertices()]
                print(f'  LWPOLYLINE: {pts}')
            elif e.dxftype() == 'LINE':
                print(f'  LINE: ({float(e.dxf.start.x):.1f}, {float(e.dxf.start.y):.1f}) -> ({float(e.dxf.end.x):.1f}, {float(e.dxf.end.y):.1f})')
            elif e.dxftype() == 'TEXT' or e.dxftype() == 'MTEXT':
                print(f'  TEXT at ({float(e.dxf.insert.x):.1f}, {float(e.dxf.insert.y):.1f}): \"{e.dxf.text}\"')
