import ezdxf
doc = ezdxf.readfile('project/10_drawings/structural/S-101_Roof_Framing_Plan_REV3.dxf')
msp = doc.modelspace()
print("Layers:")
for layer in doc.layers:
    print(f"  {layer.dxf.name}")

print("\nEntities by layer:")
layer_counts = {}
for e in msp:
    layer = e.dxf.layer
    layer_counts[layer] = layer_counts.get(layer, 0) + 1
for layer, count in sorted(layer_counts.items()):
    print(f"  {layer}: {count}")

# Look for openings and text
print("\nTEXT entities:")
for e in msp.query('TEXT'):
    print(f"  Layer: {e.dxf.layer}, Pos: ({e.dxf.insert.x:.1f}, {e.dxf.insert.y:.1f}), Text: '{e.dxf.text}'")

print("\nLWPOLYLINE entities:")
for e in msp.query('LWPOLYLINE'):
    pts = list(e.get_points())
    if len(pts) <= 10:
        print(f"  Layer: {e.dxf.layer}, {len(pts)} pts: {[(f'{p[0]:.1f}', f'{p[1]:.1f}') for p in pts]}")
    else:
        print(f"  Layer: {e.dxf.layer}, {len(pts)} pts")

EOF

